head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/



	//----W-Craft WebSquare 변환 확인: include----//
include("../js/stf.js");

	//----W-Craft WebSquare 변환 확인: include----//
include("../js/utils.js");

// grid resize 시작부

	//----W-Craft WebSquare 변환 확인: SetEvent----//
frame.SetEvent("onwinstat", OnWinStat);
scwin.iTimer = 0;
scwin.maxval = 0;
scwin.gOldWidthSize = frame.width;
scwin.gNewWidthSize = 0;
scwin.isCtrl = false;
scwin.onpageload = function() {
};
scwin.onpageunload = function() {
};
scwin.sleep = function(numberMillis) {
    var now = new Date();
    var exitTime = now.getTime() + numberMillis;
    while (true) {
        now = new Date();
        if (now.getTime() > exitTime) return;
    }

};
scwin.OnSized = function(winID) {

	//----W-Craft WebSquare 변환 확인: clearInterval----//
    if (scwin.iTimer > 0) window.clearInterval(scwin.iTimer);
    scwin.iTimer = 0;
    scwin.gNewWidthSize = frame.width;
    scwin.GauceObjResize(frame.width, frame.height);
};
scwin.OnSizedMax = function(winID) {

	//----W-Craft WebSquare 변환 확인: clearInterval----//
    if (scwin.iTimer > 0) window.clearInterval(scwin.iTimer);
    scwin.iTimer = 0;
    scwin.maxval = 0;
    scwin.GauceObjResize($c.frame.path("/").width, frame.height);
};
scwin.OnWinStat = function(winID, statmsg) {
    if (statmsg == "activate" && winID.substring(0, 6) == "Child_") {

	//----W-Craft WebSquare 변환 확인: WinActive----//
        $c.frame.path("/").WinActive(winID, statmsg);
    }
    if (statmsg == "maximize") {
        scwin.maxval = 1;
    } else if (statmsg == "size") {
        if (scwin.maxval == 0) {
            var strFnc = "OnSized('" + winID + "')";
            if (scwin.iTimer > 0) {

	//----W-Craft WebSquare 변환 확인: clearInterval----//
                window.clearInterval(scwin.iTimer);
                scwin.iTimer = 0;
            }

	//----W-Craft WebSquare 변환 확인: setInterval----//
            scwin.iTimer = window.setInterval(strFnc, 300);
        } else if (scwin.maxval == 1) {
            scwin.OnSizedMax(winID);
            scwin.gOldWidthSize = $c.frame.path("/").width - 10;
        }
    }
};
scwin.GauceObjResize = function(a, b) {
    // 그리드메인
    var gw = (a - parseInt(grd_main1.getStyle("width")) - 30);
    grd_main1.ReDraw = "false";
    grd_main2.ReDraw = "false";
    grd_main1.setGridWidth(parseInt(grd_main1.getStyle("width")) + gw);
    grd_main2.setGridWidth(parseInt(grd_main2.getStyle("width")) + gw);
    grd_main1.ReDraw = "true";
    grd_main2.ReDraw = "true";
    scwin.gOldWidthSize = frame.width;

    // 탭패널
    panel_1.style.width = parseInt(panel_1.style.width.replace("px", "")) + gw;
    panel_2.style.width = parseInt(panel_2.style.width.replace("px", "")) + gw;

    // 저장버튼
    btn_save1.style.left = parseInt(btn_save1.style.left.replace("px", "")) + gw;
    btn_save2.style.left = parseInt(btn_save2.style.left.replace("px", "")) + gw;
};

// grid resize 종료부

scwin.CopyToClipboard = function(StartRow, startColid, EndRow, EndColid, grdObj) {
    var strMatrix = "";
    var StarColIndex = grdObj.GetColumnIndex(startColid);
    var EndColIndex = grdObj.GetColumnIndex(EndColid);
    for (i = StartRow; i <= EndRow; i++) {
        for (j = StarColIndex; j <= EndColIndex; j++) {

	//----W-Craft WebSquare 변환 확인: VirtualString2----//
            strMatrix += grdObj.VirtualString2(i, grdObj.GetColumnID(j), 1);
            if (j != EndColIndex) strMatrix += "\t";
        }
        strMatrix += "\r\n";
    }
    if (strMatrix != "") {

	//----W-Craft WebSquare 변환 확인: setData----//
        window.clipboardData.setData("Text", strMatrix);
        alert("클립보드에 복사 되었습니다.");
    }
};
scwin.fn_Search1 = function() {
    var vFORM_CD = $c.stf.getObjectValue(txb_form_cd1);
    var vFORM_VER = $c.stf.getObjectValue(txb_form_ver1);
    var vFILTER = $c.stf.getObjectValue(txb_filter1);
    if (vFORM_CD == "") {
        alert("서식코드를 입력하세요.");
        txb_form_cd1.focus();
        return;
    }
    if (vFORM_VER == "") {
        alert("서식버전을 입력하세요.");
        txb_form_ver1.focus();
        return;
    }
    var url = "/NewDisclosureStatistics.do?method=listBeforeNgtDsclItems";
    url += "&FORM_CD=" + vFORM_CD;
    url += "&FORM_VER=" + vFORM_VER;
    url += "&FILTER=" + vFILTER;
    $c.stf.PanelMsg(panel_msg1, "로딩중...기다려주세요.");
    dts_acode1.DataID = encodeURI(url);

	//----W-Craft WebSquare 변환 확인: Reset----//
    dts_acode1.Reset();
};
scwin.fn_Save1 = function() {
    var res = window.confirm("저장하겠습니까?");
    if (res) {
        var url = "/NewDisclosureStatistics.do?method=saveBeforeNgtDsclItems";
        trs_save1.Action = url;
        trs_save1.KeyName = "toinb_dataid4";
        trs_save1.KeyValue = "JSP(I:pInput=dts_acode1)";

	//----W-Craft WebSquare 변환 확인: Post----//
        trs_save1.Post();
    }
};
scwin.fn_SetStckSize1 = function(pFORM_CD, pFORM_VER) {
    var res = window.confirm("다소 시간이 소요될 수 있습니다, 실행하겠습니까?");
    if (res) {
        $c.stf.PanelMsg(panel_msg1, "처리중...기다려주세요.");
        var url = "/NewDisclosureStatistics.do?method=setBeforeNgtDsclItemsStckSize";
        url += "&FORM_CD=" + pFORM_CD;
        url += "&FORM_VER=" + pFORM_VER;
        dts_parameter.SyncLoad = "true";
        dts_parameter.DataID = encodeURI(url);

	//----W-Craft WebSquare 변환 확인: Reset----//
        dts_parameter.Reset();
        dts_parameter.SyncLoad = "false";
        scwin.fn_Search1();
    }
};
scwin.fn_SetOrder1 = function(row, colid) {
    if (colid == "NEXT") {
        var vMax = 0;
        var vFORM_VER = dts_acode1.getCellData(row, "FORM_VER");
        $c.stf.setObjectValue(txb_max1, 1);
        for (var i = 1; i <= dts_acode1.getTotalRow(); i++) {
            if ((parseInt(dts_acode1.getCellData(i, "SORT_ORD"), 10) > vMax) && (dts_acode1.getCellData(i, "FORM_VER") == vFORM_VER)) {
                vMax = parseInt(dts_acode1.getCellData(i, "SORT_ORD"), 10);
            }
        }
        $c.stf.setObjectValue(txb_max1, vMax + 1);
        dts_acode1.setCellData(row, "SORT_ORD", $c.stf.getObjectValue(txb_max1));
    }
};
scwin.fn_Search2 = function() {
    var vFORM_CD = $c.stf.getObjectValue(txb_form_cd2);
    var vFORM_VER = $c.stf.getObjectValue(txb_form_ver2);
    var vFILTER = $c.stf.getObjectValue(txb_filter2);
    if (vFORM_CD == "") {
        alert("서식코드를 입력하세요.");
        txb_form_cd2.focus();
        return;
    }
    if (vFORM_VER == "") {
        alert("서식버전을입력하세요.");
        txb_form_ver2.focus();
        return;
    }
    var url = "/NewDisclosureStatistics.do?method=listAfterNgtDsclItems";
    url += "&FORM_CD=" + vFORM_CD;
    url += "&FORM_VER=" + vFORM_VER;
    url += "&FILTER=" + vFILTER;
    $c.stf.PanelMsg(panel_msg2, "로딩중...기다려주세요.");
    dts_acode2.DataID = encodeURI(url);

	//----W-Craft WebSquare 변환 확인: Reset----//
    dts_acode2.Reset();
};
