    var res = window.confirm("저장하겠습니까?");
    if (res) {
        var url = "/NewDisclosureStatistics.do?method=saveAfterNgtDsclItems";
        trs_save2.Action = url;
        trs_save2.KeyName = "toinb_dataid4";
        trs_save2.KeyValue = "JSP(I:pInput=dts_acode2)";

	//----W-Craft WebSquare 변환 확인: Post----//
        trs_save2.Post();
    }
};
