    var res = window.confirm("다소 시간이 소요될 수 있습니다, 실행하겠습니까?");
    if (res) {
        $c.stf.PanelMsg(panel_msg1, "처리중...기다려주세요.");
        var url = "/NewDisclosureStatistics.do?method=setAfterNgtDsclItemsStckSize";
        url += "&FORM_CD=" + pFORM_CD;
        url += "&FORM_VER=" + pFORM_VER;
        dts_parameter.SyncLoad = "true";
        dts_parameter.DataID = encodeURI(url);

	//----W-Craft WebSquare 변환 확인: Reset----//
