scwin.fn_SetOrder2 = function(row, colid) {
    if (colid == "NEXT") {
        var vMax = 0;
        var vFORM_VER = dts_acode2.getCellData(row, "FORM_VER");
        $c.stf.setObjectValue(txb_max2, 1);
        for (var i = 1; i <= dts_acode2.getTotalRow(); i++) {
            if ((parseInt(dts_acode2.getCellData(i, "SORT_ORD"), 10) > vMax) && (dts_acode2.getCellData(i, "FORM_VER") == vFORM_VER)) {
                vMax = parseInt(dts_acode2.getCellData(i, "SORT_ORD"), 10);
            }
        }
        $c.stf.setObjectValue(txb_max2, vMax + 1);
