scwin.grd_main1_CanColumnPosChange = function(row, colid) {
    return true;
};
scwin.grd_main2_CanColumnPosChange = function(row, colid) {
    return true;
};
scwin.gform_onload = function() {
    tab_main.setSelectedTabIndex(1);
    grd_main1.ToolTip = "use=true;header=true;alt=true;createtime=1000;destroytime=30000;fontsize=9;color=#0f0f0f;backcolor=white;edgecolor=green;";
    grd_main2.ToolTip = "use=true;header=true;alt=true;createtime=1000;destroytime=30000;fontsize=9;color=#0f0f0f;backcolor=white;edgecolor=green;";

	//----W-Craft WebSquare 변환 확인: ResetData----//

	//----W-Craft WebSquare 변환 확인: Reset----//

	//----W-Craft WebSquare 변환 확인: setData----//
    cmb_exec_type1.ResetData();
};
scwin.tab_main_OnSelChanged = async function(nIndex) {
    if ($c.frame.path("NoData") != null) {
        await $c.frame.CloseFrame();
    }
};
scwin.dts_acode1_OnLoadCompleted = function(rowcount) {
    $c.stf.PanelMsg(panel_msg1, "총 : " + $c.stf.FormatNumberEx(rowcount) + " 건");
};
scwin.dts_acode1_OnLoadError = function() {
    $c.stf.alert_error(dts_acode1);
};
scwin.trs_save1_OnFail = function() {
    $c.stf.alert_error(trs_save1);
};
scwin.trs_save1_OnSuccess = function() {
    scwin.fn_Search1();
};
scwin.txb_form_cd1_onkeypress = function() {
    if (event.keyCode == 13) {
        scwin.fn_Search1();
    }
};
scwin.txb_filter1_onkeypress = function() {
    if (event.keyCode == 13) {
        scwin.fn_Search1();
    }
};
scwin.btn_search1_onclick = function() {
    scwin.fn_Search1();
};
scwin.btn_save1_onclick = function() {
    scwin.fn_Save1();
};
scwin.grd_main1_OnDblClick = function(row, colid) {
    scwin.fn_SetOrder1(row, colid);
};
scwin.txb_form_ver1_onkeypress = function() {
    if (event.keyCode == 13) {
        scwin.fn_Search1();
    }
};
scwin.grd_main1_OnCopy = function(lStarRow, bstrStartColId, lEndRow, bstrEndColId) {
    scwin.CopyToClipboard(StartRow, startColid, EndRow, EndColid, grd_main1);
};
scwin.grd_main1_OnKeyUp = function(row, colid, data) {
    if (scwin.isCtrl == true && data == 83) {
        scwin.fn_Save1();
        return false;
    }
};
scwin.grd_main1_OnKeyPress = function(keycode) {
    if (keycode == 17) {
        scwin.isCtrl = true;
    } else {
        scwin.isCtrl = false;
    }
};
scwin.btn_exec1_onclick = function() {
    var vFORM_CD = $c.stf.getObjectValue(txb_form_cd1);
    var vFORM_VER = $c.stf.getObjectValue(txb_form_ver1);
    if (cmb_exec_type1.getSelectedIndex() < 0) {
        alert("실행할 배치작업을 선택하세요");
        txb_form_cd1.focus();
        return;
    }
    if (vFORM_CD == "") {
        alert("서식코드를 입력하세요.");
        txb_form_cd1.focus();
        return;
    }
    if (cmb_exec_type1.getSelectedIndex() == 0) {
        scwin.fn_SetStckSize1(vFORM_CD, vFORM_VER);
    }
};
scwin.dts_acode2_OnLoadCompleted = function(rowcount) {
    $c.stf.PanelMsg(panel_msg2, "총 : " + $c.stf.FormatNumberEx(rowcount) + " 건");
};
