    }
    if (cmb_exec_type2.getSelectedIndex() == 0) {
        scwin.fn_SetStckSize2(vFORM_CD, vFORM_VER);
    }
    if (cmb_exec_type2.getSelectedIndex() == 1) {
        scwin.fn_ImportItems2(vFORM_CD, vFORM_VER);
    }
};
scwin.btn_save2_onclick = function() {
    scwin.fn_Save2();
};
scwin.btn_info1_onclick = async function() {
    var url = "/extractmgt/HELP_DSCLEXTRCINFOMGT.html";
    var winTitle = "공시추출통계관리(신) 도움말";
    await $c.frame.CreateFrame("HELP_KEY", url, winTitle, 10, 10, 970, 720, "window", 0, 0, true);
};
